/**
 * The AICL token contract.
 *
 * Every visual decision a primitive makes is expressed as a CSS custom
 * property declared here. The names are public API: `@aicl/styles` and the
 * skins in `themes/` read them, and so can you. Changing a value is free;
 * changing a name is a breaking change.
 *
 * The contract is deliberately small and deliberately *semantic*. It says
 * what a thing is (`--aicl-surface`, `--aicl-text-muted`, `--aicl-danger`),
 * not what colour it happens to be. A skin overrides the values; the
 * primitives keep working.
 *
 * Three layers stack on top of it, in this order:
 *
 *   - The contract below. The default look: near-monochrome neutrals, a
 *     near-black primary, colour reserved for meaning.
 *   - A skin (`themes/*.css`). Replaces the values wholesale.
 *   - `@aicl/motion/motion.css`. Upgrades the easings to springs, and adds
 *     the interaction patterns.
 *
 * Mode and skin are separate attributes. `data-theme="light|dark"` picks the
 * mode; `data-aicl-theme="<skin>"` picks the skin. Apply both to the same
 * element — usually the AICL root — so a skin can resolve the mode itself.
 *
 * ## One palette, two modes
 *
 * A colour that differs between modes is declared once, with both values:
 *
 *   --aicl-bg: #f8f8f7;                              <- the fallback
 *   --aicl-bg: light-dark(#f8f8f7, #161616);         <- the real one
 *
 * `light-dark()` resolves against the element's used `color-scheme`, which
 * `data-theme` sets and which is inherited, so a mode set on an ancestor
 * still reaches a skin further down. The bare value above it is the
 * fallback for a browser without `light-dark()`: the second declaration is
 * dropped at parse time there, and the first one stands.
 *
 * A box-shadow is not a colour, so `light-dark()` cannot carry it. The
 * elevation ladder therefore gets its own mode blocks, below.
 */

:root {
  color-scheme: light dark;


  /* Surfaces */
  --aicl-bg: #f8f8f7;
  --aicl-bg: light-dark(#f8f8f7, #161616);
  --aicl-surface: #ffffff;
  --aicl-surface: light-dark(#ffffff, #1c1c1c);
  --aicl-surface-elevated: #ffffff;
  --aicl-surface-elevated: light-dark(#ffffff, #222222);
  --aicl-surface-inset: #f3f3f2;
  --aicl-surface-inset: light-dark(#f3f3f2, #111111);
  --aicl-surface-tint: #f1f1f0;
  --aicl-surface-tint: light-dark(#f1f1f0, #262626);
  --aicl-sidebar: #f2f2f1;
  --aicl-sidebar: light-dark(#f2f2f1, #111111);
  --aicl-overlay: rgba(10, 10, 10, 0.32);
  --aicl-overlay: light-dark(rgba(10, 10, 10, 0.32), rgba(0, 0, 0, 0.6));

  /* Text */
  --aicl-text: #18181b;
  --aicl-text: light-dark(#18181b, #f4f4f5);
  --aicl-text-muted: #52525b;
  --aicl-text-muted: light-dark(#52525b, #a1a1aa);
  --aicl-text-faint: #a1a1aa;
  --aicl-text-faint: light-dark(#a1a1aa, #71717a);
  --aicl-text-link: #2563eb;
  --aicl-text-link: light-dark(#2563eb, #60a5fa);
  --aicl-text-inverse: #fafafa;
  --aicl-text-inverse: light-dark(#fafafa, #18181b);

  /* Borders */
  --aicl-border: #e7e7e5;
  --aicl-border: light-dark(#e7e7e5, #2a2a2a);
  --aicl-border-strong: #d6d6d3;
  --aicl-border-strong: light-dark(#d6d6d3, #3a3a3a);
  --aicl-border-focus: #a1a1aa;
  --aicl-border-focus: light-dark(#a1a1aa, #71717a);

  /* Accent */
  --aicl-accent: #18181b;
  --aicl-accent: light-dark(#18181b, #fafafa);
  --aicl-accent-soft: #ececea;
  --aicl-accent-soft: light-dark(#ececea, #2a2a2a);
  --aicl-accent-strong: #09090b;
  --aicl-accent-strong: light-dark(#09090b, #ffffff);
  --aicl-accent-fg: #fafafa;
  --aicl-accent-fg: light-dark(#fafafa, #18181b);

  /* Meaning */
  --aicl-success: #16a34a;
  --aicl-success: light-dark(#16a34a, #4ade80);
  --aicl-warning: #b45309;
  --aicl-warning: light-dark(#b45309, #fbbf24);
  --aicl-danger: #dc2626;
  --aicl-danger: light-dark(#dc2626, #f87171);
  --aicl-info: #2563eb;
  --aicl-info: light-dark(#2563eb, #60a5fa);

  /* Tool states */
  --aicl-tool-pending: #a1a1aa;
  --aicl-tool-pending: light-dark(#a1a1aa, #71717a);
  --aicl-tool-running: #52525b;
  --aicl-tool-running: light-dark(#52525b, #a1a1aa);
  --aicl-tool-success: #16a34a;
  --aicl-tool-success: light-dark(#16a34a, #4ade80);
  --aicl-tool-error: #dc2626;
  --aicl-tool-error: light-dark(#dc2626, #f87171);
  --aicl-tool-cancelled: #a1a1aa;
  --aicl-tool-cancelled: light-dark(#a1a1aa, #71717a);

  /* Code */
  --aicl-code-bg: #f6f6f5;
  --aicl-code-bg: light-dark(#f6f6f5, #1f1f1f);
  --aicl-code-fg: #18181b;
  --aicl-code-fg: light-dark(#18181b, #e4e4e7);
  --aicl-code-border: #e7e7e5;
  --aicl-code-border: light-dark(#e7e7e5, #2a2a2a);
  --aicl-code-comment: #a1a1aa;
  --aicl-code-comment: light-dark(#a1a1aa, #71717a);
  --aicl-code-keyword: #b91c1c;
  --aicl-code-keyword: light-dark(#b91c1c, #fca5a5);
  --aicl-code-string: #15803d;
  --aicl-code-string: light-dark(#15803d, #86efac);
  --aicl-code-number: #1d4ed8;
  --aicl-code-number: light-dark(#1d4ed8, #93c5fd);
  --aicl-code-tag: #a16207;
  --aicl-code-tag: light-dark(#a16207, #fcd34d);

  /* Terminal */
  --aicl-terminal-bg: #18181b;
  --aicl-terminal-bg: light-dark(#18181b, #0d0d0d);
  --aicl-terminal-fg: #f4f4f5;
  --aicl-terminal-fg: light-dark(#f4f4f5, #e4e4e7);
  --aicl-terminal-prompt: #a1a1aa;
  --aicl-terminal-prompt: light-dark(#a1a1aa, #71717a);

  /* Selection and focus */
  --aicl-ring: #a1a1aa;
  --aicl-ring: light-dark(#a1a1aa, #71717a);
  --aicl-focus-ring: 0 0 0 3px color-mix(in oklab, var(--aicl-ring) 35%, transparent);
  --aicl-selection-bg: color-mix(in oklab, var(--aicl-accent) 28%, transparent);
  --aicl-shimmer-a: color-mix(in oklab, var(--aicl-text) 0%, transparent);
  --aicl-shimmer-b: color-mix(in oklab, var(--aicl-text) 7%, transparent);
  --aicl-shimmer-c: color-mix(in oklab, var(--aicl-text) 0%, transparent);

  /* Elevation. A shadow is not a colour, so these cannot ride
     `light-dark()` the way the palette does. */

  --aicl-shadow-1: 0 1px 2px rgba(0, 0, 0, 0.05);
  --aicl-shadow-2: 0 4px 16px rgba(0, 0, 0, 0.06), 0 1px 3px rgba(0, 0, 0, 0.05);
  --aicl-shadow-3: 0 16px 48px rgba(0, 0, 0, 0.14), 0 4px 12px rgba(0, 0, 0, 0.06);
  --aicl-shadow-4: 0 24px 64px rgba(0, 0, 0, 0.16), 0 8px 20px rgba(0, 0, 0, 0.08);
  --aicl-shadow-5: 0 32px 96px rgba(0, 0, 0, 0.18), 0 12px 28px rgba(0, 0, 0, 0.09);
  --aicl-shadow-6: 0 48px 144px rgba(0, 0, 0, 0.2), 0 16px 40px rgba(0, 0, 0, 0.1);

  /* ─── Type ──────────────────────────────────────────────────────
     Six roles, each a size and a leading. The roles are the theming
     axis: a skin restyles the entire type system by overriding six
     values, and every surface moves with them.

     The `--aicl-text-*` names are the raw scale, derived from the roles.
     They stay because they are the finer-grained handles — a single
     surface that needs one step off the ladder. */
  --aicl-font-sans:  'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto,
                      'Helvetica Neue', Arial, sans-serif;
  --aicl-font-mono:  ui-monospace, 'SF Mono', SFMono-Regular, 'JetBrains Mono',
                      Menlo, Consolas, monospace;

  --aicl-type-display:   17px;  --aicl-leading-display:   1.25;
  --aicl-type-title:     15px;  --aicl-leading-title:     1.35;
  --aicl-type-body:      14px;  --aicl-leading-body:      1.5;
  --aicl-type-secondary: 13px;  --aicl-leading-secondary: 1.5;
  --aicl-type-caption:   12px;  --aicl-leading-caption:   1.4;
  --aicl-type-micro:     11px;  --aicl-leading-micro:     1.3;

  --aicl-text-lg:   var(--aicl-type-display);
  --aicl-text-md:   var(--aicl-type-title);
  --aicl-text-base: var(--aicl-type-body);
  --aicl-text-sm:   var(--aicl-type-secondary);
  --aicl-text-xs:   var(--aicl-type-caption);

  --aicl-leading-tight:  1.25;
  --aicl-leading-snug:   1.4;
  --aicl-leading-normal: 1.6;

  /* ─── Radius ──────────────────────────────────────────────────── */
  --aicl-radius-sm: 6px;
  --aicl-radius-md: 10px;
  --aicl-radius-lg: 14px;
  --aicl-radius-xl: 22px;
  --aicl-radius-pill: 999px;

  /* ─── Spacing ─────────────────────────────────────────────────── */
  --aicl-space-1: 4px;
  --aicl-space-2: 8px;
  --aicl-space-3: 12px;
  --aicl-space-4: 16px;
  --aicl-space-5: 20px;
  --aicl-space-6: 28px;
  --aicl-space-7: 40px;

  /* ─── Motion ────────────────────────────────────────────────────
     Three tiers, and the rule that picks between them: the bigger the
     thing that moves, the slower it moves. The easings here are plain
     curves; `@aicl/motion/motion.css` replaces them with real springs
     without touching these durations. */
  --aicl-anim-fast: 80ms;
  --aicl-anim: 160ms;
  --aicl-anim-slow: 240ms;
  --aicl-anim-fast-exit: 60ms;
  --aicl-anim-exit: 120ms;
  --aicl-anim-slow-exit: 160ms;
  --aicl-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
  --aicl-ease-out: cubic-bezier(0, 0.6, 0.2, 1);
  --aicl-ease-in: cubic-bezier(0.4, 0, 1, 1);

  /* ─── Experience ────────────────────────────────────────────────
     The edge, the press, and the arrival. These are not colours: a skin
     that only rewrites the palette still looks like the same object.
     Surfaces in components.css read these, so one override moves every
     button, card, and dialog together. The defaults are the flat system. */
  --aicl-border-width: 1px;
  --aicl-press-y: 0px;
  --aicl-enter-y: 2px;
  --aicl-enter-rotate: 0deg;
  --aicl-dialog-enter-y: 4px;
  --aicl-dialog-enter-scale: 0.985;
  --aicl-dialog-enter-rotate: 0deg;

  /* ─── Rings ───────────────────────────────────────────────────── */
  --aicl-shadow-ring-soft: 0 0 0 1px var(--aicl-border) inset;
  --aicl-shadow-ring-strong: 0 0 0 1px var(--aicl-border-strong) inset;
}

/* The mode. `color-scheme` is inherited, so a mode set here reaches a skin
   further down the tree, and a skin's `light-dark()` values follow it. */
[data-theme='light'] { color-scheme: light; }
[data-theme='dark'] { color-scheme: dark; }

/* The elevation ladder, per mode. */
[data-theme='dark'] {
  --aicl-shadow-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --aicl-shadow-2: 0 4px 16px rgba(0, 0, 0, 0.45), 0 1px 3px rgba(0, 0, 0, 0.3);
  --aicl-shadow-3: 0 16px 48px rgba(0, 0, 0, 0.6), 0 4px 12px rgba(0, 0, 0, 0.4);
  --aicl-shadow-4: 0 24px 64px rgba(0, 0, 0, 0.62), 0 8px 20px rgba(0, 0, 0, 0.44);
  --aicl-shadow-5: 0 32px 96px rgba(0, 0, 0, 0.64), 0 12px 28px rgba(0, 0, 0, 0.46);
  --aicl-shadow-6: 0 48px 144px rgba(0, 0, 0, 0.66), 0 16px 40px rgba(0, 0, 0, 0.48);
}

/* Without an explicit mode, the system preference wins. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    --aicl-shadow-1: 0 1px 2px rgba(0, 0, 0, 0.4);
    --aicl-shadow-2: 0 4px 16px rgba(0, 0, 0, 0.45), 0 1px 3px rgba(0, 0, 0, 0.3);
    --aicl-shadow-3: 0 16px 48px rgba(0, 0, 0, 0.6), 0 4px 12px rgba(0, 0, 0, 0.4);
    --aicl-shadow-4: 0 24px 64px rgba(0, 0, 0, 0.62), 0 8px 20px rgba(0, 0, 0, 0.44);
    --aicl-shadow-5: 0 32px 96px rgba(0, 0, 0, 0.64), 0 12px 28px rgba(0, 0, 0, 0.46);
    --aicl-shadow-6: 0 48px 144px rgba(0, 0, 0, 0.66), 0 16px 40px rgba(0, 0, 0, 0.48);
  }
}

/* ─── Size ───────────────────────────────────────────────────────── */

/* One ladder, and everything with a size reads from it: the control
   height, the horizontal padding, the gap between a glyph and its label,
   the icon. A surface is dense or roomy because the ladder says so, not
   because each component decided for itself. */
:root {
  --aicl-control-height: 36px;
  --aicl-control-padding-x: 12px;
  --aicl-control-gap: 8px;
  --aicl-icon-size: 16px;
}

/* ─── Interaction ───────────────────────────────────────────────── */

/* The travelling hover highlight. One per list. */
:root {
  --aicl-hover-bg: color-mix(in oklab, var(--aicl-text) 6%, transparent);
  --aicl-hover-bg-strong: color-mix(in oklab, var(--aicl-text) 10%, transparent);

  /* The smallest comfortable target. A row that is not interactive may be
     shorter; anything you can click is at least this tall. */
  --aicl-hit: 40px;
  --aicl-hit-min: 24px;
}

/* ─── Density ────────────────────────────────────────────────────── */

/* Two densities on top of the default. `compact` is for dense surfaces —
   filter bars, toolbars, sidebars. `calm` is the same density with the
   motion taken out, for a surface that should feel still. */
[data-aicl-density='compact'] {
  --aicl-hit: 32px;
  --aicl-control-height: 28px;
  --aicl-control-padding-x: 10px;
  --aicl-control-gap: 6px;
  --aicl-icon-size: 14px;

  --aicl-type-display:   16px;
  --aicl-type-title:     14px;
  --aicl-type-body:      13px;
  --aicl-type-secondary: 12px;
  --aicl-type-caption:   11px;
  --aicl-type-micro:     10px;

  --aicl-space-1: 2px;
  --aicl-space-2: 6px;
  --aicl-space-3: 8px;
  --aicl-space-4: 12px;
  --aicl-space-5: 16px;
  --aicl-space-6: 20px;
  --aicl-space-7: 28px;
}

[data-aicl-density='calm'] {
  --aicl-hit: 28px;
  --aicl-control-height: 28px;
  --aicl-control-padding-x: 10px;
  --aicl-control-gap: 6px;
  --aicl-icon-size: 14px;

  --aicl-type-display:   16px;
  --aicl-type-title:     14px;
  --aicl-type-body:      13px;
  --aicl-type-secondary: 12px;
  --aicl-type-caption:   11px;
  --aicl-type-micro:     10px;

  --aicl-space-1: 2px;
  --aicl-space-2: 6px;
  --aicl-space-3: 8px;
  --aicl-space-4: 12px;
  --aicl-space-5: 16px;
  --aicl-space-6: 20px;
  --aicl-space-7: 28px;

  --aicl-anim-fast: 0ms;
  --aicl-anim: 0ms;
  --aicl-anim-slow: 0ms;
  --aicl-press-y: 0px;
  --aicl-enter-y: 0px;
  --aicl-enter-rotate: 0deg;
  --aicl-dialog-enter-y: 0px;
  --aicl-dialog-enter-scale: 1;
  --aicl-dialog-enter-rotate: 0deg;
}

/**
 * Component styles for every AICL primitive. The library carries `data-*`
 * attributes; this file turns them into a surface.
 *
 * The look consolidates what Devin, Manus, and Cofounder share in the
 * corpus: near-monochrome neutrals, a near-black primary, line icons,
 * full-width assistant text with a soft user bubble, agent work as quiet
 * icon-led lines rather than boxes, and a rounded card composer with a
 * toolbar row and a round send button.
 *
 * Conventions:
 *   - Every interactive element is always in the DOM; visibility is paint only.
 *   - The streaming indicator is a single reasoning row, never a caret.
 *   - Tool rows are disclosures, collapsed by default, force-open on error.
 *   - Action bars are always in the DOM and keyboard-reachable.
 */

/* ─── Shared ──────────────────────────────────────────────────────── */

[data-aicl='icon'] {
  flex: none;
  vertical-align: middle;
}

[data-aicl='icon'][data-spin] {
  animation: aicl-spin 0.9s linear infinite;
}

@keyframes aicl-spin {
  to { transform: rotate(360deg); }
}

[data-aicl='visually-hidden'] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* ─── Transcript ──────────────────────────────────────────────────── */

[data-aicl='transcript-root'] {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

[data-aicl='transcript'] {
  flex: 1;
  overflow: auto;
  /* A centred reading column: Manus, Devin, and Lovable all cap the thread. */
  padding: var(--aicl-space-5) max(var(--aicl-space-5), calc((100% - 760px) / 2)) var(--aicl-space-4);
  scrollbar-gutter: stable;
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-5);
  color: var(--aicl-text);
  font-size: var(--aicl-text-md);
  line-height: var(--aicl-leading-normal);
}

[data-aicl='transcript'][data-empty] {
  align-items: center;
  justify-content: center;
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-sm);
}

[data-aicl='scroll-to-bottom'] {
  position: absolute;
  bottom: var(--aicl-space-3);
  left: 50%;
  translate: -50% 0;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-surface-elevated);
  color: var(--aicl-text-muted);
  box-shadow: var(--aicl-shadow-2);
  cursor: pointer;
}

[data-aicl='scroll-to-bottom']:hover {
  color: var(--aicl-text);
}

[data-aicl='day-separator'] {
  display: flex;
  justify-content: center;
  margin: var(--aicl-space-2) 0 0;
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-xs);
}

/* ─── Message row ─────────────────────────────────────────────────── */

[data-aicl='message-row'] {
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-3);
}

[data-aicl='message'] {
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-2);
  width: 100%;
  min-width: 0;
  animation: aicl-message-in var(--aicl-anim) var(--aicl-ease) both;
  transform-origin: 12px 0;
}

@keyframes aicl-message-in {
  from {
    opacity: 0;
    transform: translateY(var(--aicl-enter-y)) rotate(var(--aicl-enter-rotate));
  }
}

/* Assistant: full-width text, no bubble. */
[data-aicl='message'][data-alignment='start'],
[data-aicl='message'][data-alignment='full'] {
  align-self: stretch;
}

/* User: a soft bubble on the right. */
[data-aicl='message'][data-alignment='end'] {
  align-self: flex-end;
  width: auto;
  max-width: min(80%, 620px);
  align-items: flex-end;
}

[data-aicl='message'][data-alignment='end'] [data-aicl='part'][data-part='text'] {
  padding: 10px var(--aicl-space-4);
  border-radius: var(--aicl-radius-lg);
  background: var(--aicl-bubble-user);
  white-space: pre-wrap;
}

[data-aicl='status-line'] {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-sm);
}

[data-aicl='status-line']::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: currentColor;
}

/* ─── Action bar ──────────────────────────────────────────────────── */

[data-aicl='message-actions'] {
  display: flex;
  gap: 0;
  margin-top: -2px;
  opacity: 0;
  transition: opacity var(--aicl-anim) var(--aicl-ease);
}

[data-aicl='message']:hover [data-aicl='message-actions'][data-visibility='auto'],
[data-aicl='message']:focus-within [data-aicl='message-actions'][data-visibility='auto'],
[data-aicl='message'][data-last-assistant] [data-aicl='message-actions'][data-visibility='auto'] {
  opacity: 1;
}

@media (pointer: coarse) {
  [data-aicl='message-actions'][data-visibility='auto'] {
    opacity: 1;
  }
}

[data-aicl='message-actions'] button {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: var(--aicl-radius-sm);
  background: transparent;
  color: var(--aicl-text-faint);
  cursor: pointer;
}

[data-aicl='message-actions'] button:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

[data-aicl='message-actions'] button[aria-pressed='true'] {
  color: var(--aicl-text);
}

[data-aicl='branch-switcher'] {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-xs);
  font-variant-numeric: tabular-nums;
}

[data-aicl='branch-switcher'] button {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: var(--aicl-radius-sm);
  background: transparent;
  color: inherit;
  cursor: pointer;
}

[data-aicl='branch-switcher'] button:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

/* ─── Parts ───────────────────────────────────────────────────────── */

[data-aicl='part'][data-part='text'] {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

[data-aicl='part'][data-part='unknown'],
[data-aicl='part'][data-part='tool-result'] {
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-xs);
  font-family: var(--aicl-font-mono);
}

[data-aicl='part'][data-part='tool-result'][data-is-error] {
  color: var(--aicl-danger);
}

/* Reasoning and tool calls: quiet icon-led lines (Devin "Thought for 9s"). */
[data-aicl='reasoning'] > button,
[data-aicl='tool-call'] > button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  max-width: 100%;
  padding: 2px 0;
  border: 0;
  background: transparent;
  color: var(--aicl-text-muted);
  font: inherit;
  font-size: var(--aicl-text-sm);
  text-align: start;
  cursor: pointer;
}

[data-aicl='reasoning'] > button:hover,
[data-aicl='tool-call'] > button:hover {
  color: var(--aicl-text);
}

[data-aicl='reasoning'] > button > span,
[data-aicl='tool-call'] > button > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The trailing chevron rotates open; it is the last icon in the row. */
[data-aicl='reasoning'] > button > [data-aicl='icon']:last-child:not(:first-child),
[data-aicl='tool-call'] > button > [data-aicl='icon']:last-child {
  color: var(--aicl-text-faint);
  opacity: 0;
  transition: transform var(--aicl-anim) var(--aicl-ease), opacity var(--aicl-anim) var(--aicl-ease);
}

[data-aicl='reasoning'] > button:hover > [data-aicl='icon']:last-child,
[data-aicl='tool-call'] > button:hover > [data-aicl='icon']:last-child,
[data-aicl='reasoning'][data-state='open'] > button > [data-aicl='icon']:last-child,
[data-aicl='tool-call'][data-open] > button > [data-aicl='icon']:last-child {
  opacity: 1;
}

[data-aicl='reasoning'][data-state='open'] > button > [data-aicl='icon']:last-child,
[data-aicl='tool-call'][data-open] > button > [data-aicl='icon']:last-child {
  transform: rotate(90deg);
}

[data-aicl='reasoning'][data-state='pending'] > button > span {
  background: linear-gradient(90deg, var(--aicl-text-faint) 0%, var(--aicl-text) 50%, var(--aicl-text-faint) 100%);
  background-size: 200% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  animation: aicl-text-shimmer 1.6s linear infinite;
}

@keyframes aicl-text-shimmer {
  from { background-position: 200% 0; }
  to   { background-position: -200% 0; }
}

[data-aicl='reasoning-body'] {
  margin: 6px 0 2px 7px;
  padding-left: 15px;
  border-left: 1px solid var(--aicl-border);
  color: var(--aicl-text-muted);
  font-size: var(--aicl-text-sm);
  white-space: pre-wrap;
}

[data-aicl='tool-call'][data-status='success'] > button > [data-aicl='icon']:first-child { color: var(--aicl-tool-success); }
[data-aicl='tool-call'][data-status='error'] > button { color: var(--aicl-tool-error); }
[data-aicl='tool-call'][data-status='cancelled'] > button { color: var(--aicl-text-faint); }

[data-aicl='tool-call-body'] {
  margin: 6px 0 2px 7px;
  padding: var(--aicl-space-2) var(--aicl-space-3);
  max-height: 240px;
  overflow: auto;
  border: 1px solid var(--aicl-code-border);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-code-bg);
  color: var(--aicl-code-fg);
  font-family: var(--aicl-font-mono);
  font-size: var(--aicl-text-xs);
  line-height: 1.5;
  white-space: pre-wrap;
}

/* ─── Artifact card (Manus document card, Lovable code chip) ──────── */

[data-aicl='artifact-card'] {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas: 'icon title open' 'icon meta open' 'body body body';
  align-items: center;
  column-gap: var(--aicl-space-3);
  max-width: 520px;
  padding: var(--aicl-space-3) var(--aicl-space-4);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-lg);
  background: var(--aicl-surface);
  box-shadow: var(--aicl-shadow-1);
}

[data-aicl='artifact-card'][data-openable]:hover {
  border-color: var(--aicl-border-strong);
}

[data-aicl='artifact-icon'] {
  grid-area: icon;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface-inset);
  color: var(--aicl-text-muted);
}

[data-aicl='artifact-title'] {
  grid-area: title;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--aicl-text-base);
  font-weight: 500;
}

[data-aicl='artifact-meta'] {
  grid-area: meta;
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-xs);
}

[data-aicl='artifact-kind'] {
  text-transform: capitalize;
}

[data-aicl='artifact-version']::before {
  content: ' · ';
}

[data-aicl='artifact-open'] {
  grid-area: open;
  padding: 5px var(--aicl-space-3);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface);
  color: var(--aicl-text);
  font: inherit;
  font-size: var(--aicl-text-sm);
  font-weight: 500;
  cursor: pointer;
}

[data-aicl='artifact-open']:hover {
  background: var(--aicl-surface-tint);
}

[data-aicl='artifact-card'] > [data-aicl='terminal-output'] {
  grid-area: body;
  margin-top: var(--aicl-space-3);
}

/* ─── Terminal ────────────────────────────────────────────────────── */

[data-aicl='terminal-output'] {
  max-height: 280px;
  overflow: auto;
  padding: var(--aicl-space-3);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-terminal-bg);
  color: var(--aicl-terminal-fg);
  font-family: var(--aicl-font-mono);
  font-size: var(--aicl-text-xs);
  line-height: 1.6;
  white-space: pre-wrap;
}

[data-aicl='terminal-output'][data-streaming]::after {
  content: '▍';
  animation: aicl-blink 1s steps(2) infinite;
}

@keyframes aicl-blink {
  50% { opacity: 0; }
}

/* ─── Code block ──────────────────────────────────────────────────── */

[data-aicl='code-block'] {
  position: relative;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--aicl-code-border);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-code-bg);
}

[data-aicl='code-block'] figcaption {
  padding: 6px var(--aicl-space-3);
  border-bottom: 1px solid var(--aicl-code-border);
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-xs);
}

[data-aicl='code-block'] pre {
  margin: 0;
  padding: var(--aicl-space-3);
  overflow-x: auto;
  color: var(--aicl-code-fg);
  font-family: var(--aicl-font-mono);
  font-size: var(--aicl-text-sm);
  line-height: 1.55;
}

[data-aicl='code-block'] [aria-label='Copy code'] {
  position: absolute;
  top: 4px;
  right: 4px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: 0;
  border-radius: var(--aicl-radius-sm);
  background: transparent;
  color: var(--aicl-text-faint);
  font: inherit;
  font-size: var(--aicl-text-xs);
  cursor: pointer;
  opacity: 0;
  transition: opacity var(--aicl-anim) var(--aicl-ease);
}

[data-aicl='code-block']:hover [aria-label='Copy code'],
[data-aicl='code-block']:focus-within [aria-label='Copy code'],
[data-aicl='code-block'][data-copied] [aria-label='Copy code'] {
  opacity: 1;
}

[data-aicl='code-block'] [aria-label='Copy code']:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

[data-aicl='code-block'][data-inline] {
  display: inline;
  border: 0;
}

/* ─── File, error, suggestions ────────────────────────────────────── */

[data-aicl='part'][data-part='file'] > button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px var(--aicl-space-3);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface);
  color: var(--aicl-text);
  font: inherit;
  font-size: var(--aicl-text-sm);
  cursor: pointer;
}

[data-aicl='part'][data-part='file'] > button:hover {
  background: var(--aicl-surface-tint);
}

[data-aicl='part'][data-part='file'][data-state='uploading'] {
  opacity: 0.7;
}

[data-aicl='part'][data-part='error'] {
  display: flex;
  align-items: center;
  gap: var(--aicl-space-2);
  padding: 10px var(--aicl-space-3);
  border: 1px solid color-mix(in oklab, var(--aicl-danger) 30%, var(--aicl-border));
  border-radius: var(--aicl-radius-md);
  background: color-mix(in oklab, var(--aicl-danger) 6%, var(--aicl-surface));
  color: var(--aicl-danger);
  font-size: var(--aicl-text-sm);
}

[data-aicl='part'][data-part='error'] p {
  flex: 1;
  margin: 0;
  color: var(--aicl-text);
}

[data-aicl='part'][data-part='error'] button[aria-label='Retry'] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-sm);
  background: var(--aicl-surface);
  color: var(--aicl-text);
  font: inherit;
  font-size: var(--aicl-text-sm);
  cursor: pointer;
}

[data-aicl='part'][data-part='error'] button[aria-label='Retry']:hover {
  background: var(--aicl-surface-tint);
}

[data-aicl='part'][data-part='data-suggested-followups'] {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  border-top: 1px solid var(--aicl-border);
}

[data-aicl='part'][data-part='data-suggested-followups'] button {
  width: 100%;
  padding: 10px 2px;
  border: 0;
  border-bottom: 1px solid var(--aicl-border);
  background: transparent;
  color: var(--aicl-text-muted);
  font: inherit;
  font-size: var(--aicl-text-sm);
  text-align: start;
  cursor: pointer;
}

[data-aicl='part'][data-part='data-suggested-followups'] button:hover {
  color: var(--aicl-text);
}

/* ─── Plan checklist (Manus step list, Devin "7/7 Test the app") ──── */

[data-aicl='plan-checklist'] {
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-2);
  padding: var(--aicl-space-3) var(--aicl-space-4);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-lg);
  background: var(--aicl-surface);
  font-size: var(--aicl-text-sm);
}

[data-aicl='plan-rollup'] {
  display: flex;
  justify-content: space-between;
  margin: 0;
  color: var(--aicl-text-muted);
}

[data-aicl='plan-title'] {
  color: var(--aicl-text);
  font-weight: 500;
}

[data-aicl='plan-count'] {
  font-variant-numeric: tabular-nums;
}

[data-aicl='plan-checklist'] ol {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

[data-aicl='plan-checklist'] li {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--aicl-text-muted);
}

[data-aicl='plan-checklist'] li[data-status='pending'] { color: var(--aicl-text-faint); }
[data-aicl='plan-checklist'] li[data-status='running'] { color: var(--aicl-text); }
[data-aicl='plan-checklist'] li[data-status='done'] [data-aicl='icon'] { color: var(--aicl-tool-success); }
[data-aicl='plan-checklist'] li[data-status='error'] [data-aicl='icon'] { color: var(--aicl-tool-error); }

/* ─── Composer: a rounded card with a toolbar row (Manus, Devin) ──── */

[data-aicl='composer'] {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    'chips chips chips'
    'files files files'
    'input input input'
    'attach reason submit';
  align-items: center;
  gap: 0 var(--aicl-space-2);
  padding: var(--aicl-space-3) var(--aicl-space-3) var(--aicl-space-2);
  border: var(--aicl-border-width) solid var(--aicl-border);
  border-radius: var(--aicl-radius-xl);
  background: var(--aicl-surface);
  box-shadow: var(--aicl-shadow-2);
  transition:
    border-color var(--aicl-anim) var(--aicl-ease),
    box-shadow var(--aicl-anim) var(--aicl-ease),
    transform var(--aicl-anim) var(--aicl-ease);
}

[data-aicl='composer']:focus-within {
  border-color: var(--aicl-border-strong);
}

[data-aicl='composer'][data-state='error'] {
  border-color: color-mix(in oklab, var(--aicl-danger) 45%, var(--aicl-border));
}

[data-aicl='composer'][data-placement='hero'] {
  padding: var(--aicl-space-4) var(--aicl-space-4) var(--aicl-space-3);
}

[data-aicl='composer'][data-placement='hero'] [data-aicl='composer-input'] {
  min-height: 56px;
  font-size: var(--aicl-text-md);
}

[data-aicl='composer'][data-placement='rail'] {
  border-radius: var(--aicl-radius-lg);
  box-shadow: none;
}

[data-aicl='composer'] > [data-aicl='suggestion-chips'] {
  grid-area: chips;
  margin-bottom: var(--aicl-space-2);
}

[data-aicl='attachment-row'] {
  grid-area: files;
  display: flex;
  flex-wrap: wrap;
  gap: var(--aicl-space-1);
  margin: 0 var(--aicl-space-1) var(--aicl-space-2);
}

[data-aicl='composer-input'] {
  grid-area: input;
  width: 100%;
  min-height: 28px;
  margin: 0 0 var(--aicl-space-2);
  padding: 2px var(--aicl-space-1);
  border: 0;
  outline: none;
  box-shadow: none;
  resize: none;
  background: transparent;
  color: var(--aicl-text);
  font: inherit;
  font-size: var(--aicl-text-md);
  line-height: var(--aicl-leading-normal);
}

[data-aicl='composer-input']::placeholder {
  color: var(--aicl-text-faint);
}

[data-aicl='composer-attach'] {
  grid-area: attach;
  justify-self: start;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-pill);
  background: transparent;
  color: var(--aicl-text-muted);
  cursor: pointer;
}

[data-aicl='composer-attach']:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

[data-aicl='composer-disabled-reason'] {
  grid-area: reason;
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-xs);
}

[data-aicl='composer-submit'] {
  grid-area: submit;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-accent);
  color: var(--aicl-accent-fg);
  cursor: pointer;
  transition: opacity var(--aicl-anim-fast) var(--aicl-ease), background var(--aicl-anim-fast) var(--aicl-ease);
}

[data-aicl='composer-submit']:disabled {
  background: var(--aicl-surface-inset);
  color: var(--aicl-text-faint);
  cursor: default;
}

[data-aicl='composer-submit']:not(:disabled):hover {
  opacity: 0.85;
}

[data-aicl='composer-submit'][data-role='stop'] [data-aicl='icon'] {
  fill: currentColor;
}

/* ─── Button ────────────────────────────────────────────────────── */

/* The button primitive. A flat control with three axes — variant, size
   and loading — published as attributes so a skin can restyle it
   without touching the component. */
[data-aicl='button'] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--aicl-control-gap);
  height: var(--aicl-control-height);
  padding: 0 var(--aicl-control-padding-x);
  border: var(--aicl-border-width) solid transparent;
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-accent);
  color: var(--aicl-accent-fg);
  font: inherit;
  font-size: var(--aicl-type-secondary);
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background var(--aicl-anim-fast) var(--aicl-ease),
    border-color var(--aicl-anim-fast) var(--aicl-ease),
    color var(--aicl-anim-fast) var(--aicl-ease),
    opacity var(--aicl-anim-fast) var(--aicl-ease),
    box-shadow var(--aicl-anim-fast) var(--aicl-ease),
    transform var(--aicl-anim-fast) var(--aicl-ease);
}

[data-aicl='button'][data-variant='secondary'] {
  background: var(--aicl-surface);
  border-color: var(--aicl-border);
  color: var(--aicl-text);
}

[data-aicl='button'][data-variant='outline'] {
  background: transparent;
  border-color: var(--aicl-border-strong);
  color: var(--aicl-text);
}

[data-aicl='button'][data-variant='ghost'] {
  background: transparent;
  color: var(--aicl-text);
}

[data-aicl='button'][data-variant='link'] {
  background: transparent;
  color: var(--aicl-text-link);
  text-decoration: underline;
  text-underline-offset: 2px;
}

[data-aicl='button'][data-variant='destructive'] {
  background: var(--aicl-danger);
  color: var(--aicl-surface);
}

[data-aicl='button'][data-size='sm'] {
  height: 28px;
  padding: 0 var(--aicl-space-2);
  font-size: var(--aicl-type-caption);
}

[data-aicl='button'][data-size='lg'] {
  height: 44px;
  padding: 0 var(--aicl-space-5);
  font-size: var(--aicl-type-body);
}

[data-aicl='button']:not(:disabled):hover {
  opacity: 0.88;
}

[data-aicl='button']:not(:disabled):active {
  transform: translateY(var(--aicl-press-y));
}

[data-aicl='button']:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

[data-aicl='button'][data-loading] {
  cursor: progress;
  opacity: 0.7;
}

[data-aicl='button-icon'] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

[data-aicl='button-label'] {
  min-width: 0;
}

/* An icon-only button is a circle. */
[data-aicl='button']:not(:has([data-aicl='button-label'])) {
  width: var(--aicl-control-height);
  padding: 0;
  border-radius: var(--aicl-radius-pill);
}

/* ─── Composer, compound ─────────────────────────────────────────── */

/* The field area. The default arrangement does not use it; a consumer
   who arranges the composer puts the attach action and the field here. */
[data-aicl='composer-body'] {
  grid-area: input;
  display: flex;
  align-items: flex-end;
  gap: var(--aicl-space-2);
  min-width: 0;
}

[data-aicl='composer-body'] [data-aicl='composer-input'] {
  flex: 1;
  min-width: 0;
}

[data-aicl='composer-hint'] {
  margin: 0;
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-caption);
  line-height: var(--aicl-leading-caption);
}

/* ─── Suggestion chips: quiet pills above the field. ─────────────── */
[data-aicl='suggestion-chips'] {
  display: flex;
  flex-wrap: wrap;
  gap: var(--aicl-space-2);
}

[data-aicl='suggestion-chip'] {
  padding: 5px var(--aicl-space-3);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-surface);
  color: var(--aicl-text-muted);
  font: inherit;
  font-size: var(--aicl-text-sm);
  cursor: pointer;
}

[data-aicl='suggestion-chip']:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

[data-aicl='attachment-chip'] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 260px;
  padding: 4px 4px 4px 8px;
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface);
  color: var(--aicl-text-muted);
  font-size: var(--aicl-text-xs);
}

[data-aicl='attachment-icon'] {
  display: grid;
  place-items: center;
  color: var(--aicl-text-faint);
}

/* ═══ Composer surface: trigger menu, chips, attachments ══════════════ */

[data-aicl='trigger-menu'] {
  position: relative;
}

[data-aicl='trigger-menu'] [role='listbox'] {
  position: absolute;
  bottom: calc(100% + var(--aicl-space-2));
  left: 0;
  z-index: 20;
  min-width: 240px;
  max-height: 280px;
  overflow-y: auto;
  margin: 0;
  padding: var(--aicl-space-1);
  list-style: none;
  background: var(--aicl-surface-elevated);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-md);
  box-shadow: var(--aicl-shadow-2);
  font-size: var(--aicl-text-sm);
}

[data-aicl='trigger-menu'] [role='option'],
[data-aicl='trigger-menu-empty'] {
  padding: 6px var(--aicl-space-3);
  border-radius: var(--aicl-radius-sm);
  color: var(--aicl-text);
  cursor: default;
}

[data-aicl='trigger-menu-empty'] {
  color: var(--aicl-text-faint);
}

[data-aicl='trigger-menu'] [role='option'][data-active] {
  background: var(--aicl-accent-soft);
  color: var(--aicl-accent-strong);
}

[data-aicl='trigger-menu'] [role='option'][aria-disabled='true'] {
  color: var(--aicl-text-faint);
}

[data-aicl='suggestion-chip']:focus-visible {
  outline: 2px solid var(--aicl-ring);
  outline-offset: 2px;
}

[data-aicl='attachment-chip'][data-has-preview] {
  padding-left: 2px;
}

[data-aicl='attachment-preview'] {
  width: 24px;
  height: 24px;
  object-fit: cover;
  border-radius: calc(var(--aicl-radius-sm) - 2px);
}

[data-aicl='attachment-name'] {
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--aicl-text);
}

[data-aicl='attachment-size'] {
  color: var(--aicl-text-faint);
}

[data-aicl='attachment-progress'] {
  position: relative;
  width: 40px;
  height: 4px;
  overflow: hidden;
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-border);
}

[data-aicl='attachment-progress']::after {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--aicl-attachment-progress, 40%);
  background: var(--aicl-accent);
  animation: aicl-indeterminate 1.2s var(--aicl-ease) infinite;
}

@keyframes aicl-indeterminate {
  from { transform: translateX(-100%); }
  to   { transform: translateX(250%); }
}

[data-aicl='attachment-chip'][data-status='error'] {
  border-color: color-mix(in oklab, var(--aicl-danger) 45%, var(--aicl-border));
}

[data-aicl='attachment-error'] {
  color: var(--aicl-danger);
  white-space: nowrap;
}

[data-aicl='attachment-remove'],
[data-aicl='attachment-retry'] {
  padding: 0 4px;
  border: 0;
  background: transparent;
  color: var(--aicl-text-muted);
  font: inherit;
  border-radius: var(--aicl-radius-sm);
  cursor: pointer;
}

[data-aicl='attachment-remove']:hover,
[data-aicl='attachment-retry']:hover {
  background: var(--aicl-surface-inset);
  color: var(--aicl-text);
}

[data-aicl='attachment-dropzone'] {
  position: relative;
  border-radius: var(--aicl-radius-lg);
}

[data-aicl='attachment-dropzone'][data-dragover]::after {
  content: 'Drop to attach';
  position: absolute;
  inset: 0;
  z-index: 10;
  display: grid;
  place-items: center;
  border: 2px dashed var(--aicl-accent);
  border-radius: inherit;
  background: color-mix(in oklab, var(--aicl-accent-soft) 85%, transparent);
  color: var(--aicl-accent-strong);
  font-size: var(--aicl-text-sm);
  font-weight: 500;
  pointer-events: none;
}

/* ═══ Sessions & navigation ═══════════════════════════════════════════ */

[data-aicl='session-list'],
[data-aicl='session-search'] {
  display: flex;
  flex-direction: column;
  min-height: 0;
  font-size: var(--aicl-text-sm);
  color: var(--aicl-text);
}

[data-aicl='session-list-header'] {
  flex: none;
  padding: var(--aicl-space-2);
}

[data-aicl='session-listbox'],
[data-aicl='session-search-results'] {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: var(--aicl-space-1);
  outline: none;
}

[data-aicl='session-listbox']:focus-visible {
  box-shadow: inset 0 0 0 2px var(--aicl-ring);
  border-radius: var(--aicl-radius-md);
}

[data-aicl='session-group'] + [data-aicl='session-group'] {
  margin-top: var(--aicl-space-3);
}

[data-aicl='session-group-label'] {
  padding: var(--aicl-space-2) var(--aicl-space-3) var(--aicl-space-1);
  font-size: var(--aicl-text-xs);
  font-weight: 500;
  color: var(--aicl-text-faint);
}

[data-aicl='session-item'] {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: 'title actions' 'secondary actions';
  align-items: center;
  column-gap: var(--aicl-space-2);
  padding: 6px var(--aicl-space-3);
  border-radius: var(--aicl-radius-sm);
  cursor: pointer;
}

[data-aicl='session-item']:hover {
  background: var(--aicl-surface-tint);
}

[data-aicl='session-item'][data-active] {
  background: var(--aicl-accent-soft);
}

[data-aicl='session-item'][aria-selected='true'] [data-aicl='session-title'] {
  color: var(--aicl-accent-strong);
}

[data-aicl='session-title'] {
  grid-area: title;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-aicl='session-item'][data-unread] [data-aicl='session-title'] {
  font-weight: 600;
}

[data-aicl='session-item'][data-unread]::before {
  content: '';
  position: absolute;
  left: 2px;
  top: 50%;
  width: 5px;
  height: 5px;
  margin-top: -2.5px;
  border-radius: 50%;
  background: var(--aicl-accent);
}

[data-aicl='session-secondary'] {
  grid-area: secondary;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--aicl-text-xs);
  color: var(--aicl-text-faint);
}

[data-aicl='session-item'][data-status='running'] [data-aicl='session-secondary'] {
  color: var(--aicl-tool-running);
}

[data-aicl='session-item'][data-status='awaiting-input'] [data-aicl='session-secondary'] {
  color: var(--aicl-warning);
}

[data-aicl='session-item'][data-status='error'] [data-aicl='session-secondary'] {
  color: var(--aicl-danger);
}

[data-aicl='session-item'][data-archived] {
  opacity: 0.6;
}

/* Always in the DOM; revealed on hover or focus-within (never display:none). */
[data-aicl='session-actions'] {
  grid-area: actions;
  display: flex;
  gap: 2px;
  opacity: 0;
  transition: opacity var(--aicl-anim-fast) var(--aicl-ease);
}

[data-aicl='session-item']:hover [data-aicl='session-actions'],
[data-aicl='session-item']:focus-within [data-aicl='session-actions'],
[data-aicl='session-item'][data-active] [data-aicl='session-actions'] {
  opacity: 1;
}

[data-aicl='session-actions'] button {
  padding: 2px 6px;
  border: 0;
  background: transparent;
  font: inherit;
  font-size: var(--aicl-text-xs);
  color: var(--aicl-text-muted);
  border-radius: var(--aicl-radius-sm);
  cursor: pointer;
}

[data-aicl='session-actions'] button:hover {
  background: var(--aicl-surface-inset);
  color: var(--aicl-text);
}

[data-aicl='session-skeleton'] {
  height: 36px;
  margin: 4px var(--aicl-space-1);
  border-radius: var(--aicl-radius-sm);
  background: linear-gradient(90deg, var(--aicl-shimmer-a), var(--aicl-shimmer-b), var(--aicl-shimmer-c));
  background-size: 200% 100%;
  animation: aicl-shimmer 1.4s linear infinite;
}

@keyframes aicl-shimmer {
  from { background-position: 200% 0; }
  to   { background-position: -200% 0; }
}

[data-aicl='session-list-empty'],
[data-aicl='session-search-empty'] {
  padding: var(--aicl-space-5) var(--aicl-space-3);
  text-align: center;
  color: var(--aicl-text-faint);
}

[data-aicl='session-search-input'] {
  margin: var(--aicl-space-2);
  padding: 8px var(--aicl-space-3);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface);
  color: var(--aicl-text);
  font: inherit;
}

[data-aicl='session-search-input']:focus {
  outline: none;
  border-color: var(--aicl-border-focus);
  box-shadow: var(--aicl-focus-ring);
}

[data-aicl='session-search-status'],
[data-aicl='field-save-state']:empty {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

[data-aicl='sidebar-nav'] {
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-1);
  padding: var(--aicl-space-2);
  font-size: var(--aicl-text-sm);
}

[data-aicl='sidebar-nav-toggle'] {
  align-self: flex-end;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: var(--aicl-radius-sm);
  background: transparent;
  color: var(--aicl-text-muted);
  cursor: pointer;
}

[data-aicl='sidebar-nav-toggle'] {
  display: grid;
  place-items: center;
}

[data-aicl='sidebar-nav'][data-state='collapsed'] [data-aicl='sidebar-nav-toggle'] {
  align-self: center;
}

[data-aicl='sidebar-nav-toggle']:hover {
  background: var(--aicl-surface-tint);
}

[data-aicl='sidebar-nav-list'] {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

[data-aicl='sidebar-nav-item'] {
  display: flex;
  align-items: center;
  gap: var(--aicl-space-2);
  width: 100%;
  padding: 6px var(--aicl-space-2);
  border: 0;
  border-radius: var(--aicl-radius-sm);
  background: transparent;
  color: var(--aicl-text-muted);
  font: inherit;
  text-align: start;
  text-decoration: none;
  cursor: pointer;
}

[data-aicl='sidebar-nav-item']:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

[data-aicl='sidebar-nav-item'][data-active] {
  background: var(--aicl-accent-soft);
  color: var(--aicl-accent-strong);
  font-weight: 500;
}

[data-aicl='sidebar-nav-icon'] {
  display: inline-grid;
  place-items: center;
  width: 20px;
  flex: none;
}

[data-aicl='sidebar-nav-badge'] {
  margin-left: auto;
  padding: 0 6px;
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-surface-inset);
  font-size: var(--aicl-text-xs);
}

/* Collapsed: the label is visually hidden but stays the accessible name. */
[data-aicl='sidebar-nav-item'][data-collapsed] {
  justify-content: center;
}

[data-aicl='sidebar-nav-item'][data-collapsed] [data-aicl='sidebar-nav-label'],
[data-aicl='sidebar-nav-item'][data-collapsed] [data-aicl='sidebar-nav-badge'] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* ═══ Overlays ════════════════════════════════════════════════════════ */

[data-aicl='dialog-layer'],
[data-aicl='alert-dialog-layer'],
[data-aicl='drawer-layer'] {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: var(--aicl-space-4);
  font-family: var(--aicl-font-sans);
  font-size: var(--aicl-text-base);
  line-height: var(--aicl-leading-normal);
  color: var(--aicl-text);
}

[data-aicl='scrim'] {
  position: absolute;
  inset: 0;
  background: var(--aicl-overlay);
  animation: aicl-fade-in var(--aicl-anim) var(--aicl-ease-out);
}

[data-aicl='dialog'],
[data-aicl='alert-dialog'],
[data-aicl='drawer'] {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-3);
  max-height: calc(100vh - 2 * var(--aicl-space-4));
  overflow-y: auto;
  padding: var(--aicl-space-5);
  background: var(--aicl-surface-elevated);
  border: var(--aicl-border-width) solid var(--aicl-border);
  border-radius: var(--aicl-radius-lg);
  box-shadow: var(--aicl-shadow-3);
  outline: none;
  animation: aicl-dialog-in var(--aicl-anim-slow) var(--aicl-ease-out);
}

[data-aicl='dialog'][data-size='sm'],
[data-aicl='alert-dialog'] { width: min(400px, 100%); }
[data-aicl='dialog'][data-size='md'] { width: min(560px, 100%); }
[data-aicl='dialog'][data-size='lg'] { width: min(85vw, 1100px); height: 85vh; max-height: 85vh; }

[data-aicl='dialog-title'] {
  margin: 0;
  padding-right: var(--aicl-space-6);
  font-size: var(--aicl-text-lg);
  font-weight: 600;
  line-height: var(--aicl-leading-tight);
}

[data-aicl='dialog-description'] {
  margin: 0;
  color: var(--aicl-text-muted);
  font-size: var(--aicl-text-sm);
}

[data-aicl='dialog-close'] {
  position: absolute;
  top: var(--aicl-space-3);
  right: var(--aicl-space-3);
  padding: 4px 8px;
  border: 0;
  border-radius: var(--aicl-radius-sm);
  background: transparent;
  color: var(--aicl-text-muted);
  font: inherit;
  font-size: var(--aicl-text-sm);
  cursor: pointer;
}

[data-aicl='dialog-close']:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

[data-aicl='alert-dialog-confirmation'] {
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-1);
  font-size: var(--aicl-text-sm);
  color: var(--aicl-text-muted);
}

[data-aicl='alert-dialog-confirmation'] input,
[data-aicl='field'] input,
[data-aicl='field'] textarea {
  padding: 7px var(--aicl-space-3);
  border: 1px solid var(--aicl-border-strong);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface);
  color: var(--aicl-text);
  font: inherit;
  font-size: var(--aicl-text-sm);
}

[data-aicl='alert-dialog-confirmation'] input:focus,
[data-aicl='field'] input:focus,
[data-aicl='field'] textarea:focus {
  outline: none;
  border-color: var(--aicl-border-focus);
  box-shadow: var(--aicl-focus-ring);
}

[data-aicl='alert-dialog-actions'] {
  display: flex;
  justify-content: flex-end;
  gap: var(--aicl-space-2);
  margin-top: var(--aicl-space-2);
}

[data-aicl='alert-dialog-cancel'],
[data-aicl='alert-dialog-confirm'],
[data-aicl='toast-action'] {
  padding: 7px var(--aicl-space-4);
  border: 1px solid var(--aicl-border-strong);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface);
  color: var(--aicl-text);
  font: inherit;
  font-size: var(--aicl-text-sm);
  font-weight: 500;
  cursor: pointer;
}

[data-aicl='alert-dialog-confirm'][data-variant='danger'] {
  border-color: var(--aicl-danger);
  background: var(--aicl-danger);
  color: var(--aicl-text-inverse);
}

[data-aicl='alert-dialog-confirm'][data-variant='warning'] {
  border-color: var(--aicl-warning);
  background: var(--aicl-warning);
  color: var(--aicl-text-inverse);
}

[data-aicl='alert-dialog-confirm']:disabled,
[data-aicl='alert-dialog-cancel']:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

[data-aicl='alert-dialog-confirm'][aria-busy='true'] {
  cursor: progress;
}

[data-aicl='drawer-layer'] {
  padding: 0;
}

[data-aicl='drawer'] {
  position: absolute;
  max-height: none;
  border-radius: 0;
  --aicl-drawer-drag: 0px;
}

[data-aicl='drawer'][data-side='right'] { top: 0; right: 0; bottom: 0; width: min(420px, 92vw); transform: translateX(var(--aicl-drawer-drag)); }
[data-aicl='drawer'][data-side='left'] { top: 0; left: 0; bottom: 0; width: min(420px, 92vw); transform: translateX(calc(-1 * var(--aicl-drawer-drag))); }
[data-aicl='drawer'][data-side='bottom'] {
  left: 0;
  right: 0;
  bottom: 0;
  max-height: 85vh;
  border-radius: var(--aicl-radius-lg) var(--aicl-radius-lg) 0 0;
  transform: translateY(var(--aicl-drawer-drag));
}

[data-aicl='drawer'][data-state='dragging'] {
  animation: none;
  user-select: none;
}

@keyframes aicl-fade-in {
  from { opacity: 0; }
}

@keyframes aicl-dialog-in {
  from {
    opacity: 0;
    transform:
      translateY(var(--aicl-dialog-enter-y))
      scale(var(--aicl-dialog-enter-scale))
      rotate(var(--aicl-dialog-enter-rotate));
  }
}

/* ═══ Toasts ══════════════════════════════════════════════════════════ */

[data-aicl='toast-region'] {
  position: fixed;
  z-index: 1100;
  display: flex;
  flex-direction: column;
  gap: var(--aicl-space-2);
  width: min(380px, calc(100vw - 2 * var(--aicl-space-4)));
  font-family: var(--aicl-font-sans);
  pointer-events: none;
}

[data-aicl='toast-region'][data-placement='bottom-end'] { right: var(--aicl-space-4); bottom: var(--aicl-space-4); }
[data-aicl='toast-region'][data-placement='bottom-start'] { left: var(--aicl-space-4); bottom: var(--aicl-space-4); }
[data-aicl='toast-region'][data-placement='top-start'] { left: var(--aicl-space-4); top: var(--aicl-space-4); }
[data-aicl='toast-region'][data-placement='top-center'] { left: 50%; top: var(--aicl-space-4); transform: translateX(-50%); }

[data-aicl='toast'] {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 2px var(--aicl-space-3);
  padding: var(--aicl-space-3) var(--aicl-space-4);
  padding-right: var(--aicl-space-6);
  background: var(--aicl-surface-elevated);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-md);
  box-shadow: var(--aicl-shadow-2);
  color: var(--aicl-text);
  font-size: var(--aicl-text-sm);
  pointer-events: auto;
  animation: aicl-dialog-in var(--aicl-anim) var(--aicl-ease-out);
}


[data-aicl='toast-title'] { grid-column: 2; font-weight: 500; }
[data-aicl='toast-description'] { grid-column: 2; color: var(--aicl-text-muted); }
[data-aicl='toast-action'] { grid-column: 3; grid-row: 1 / span 2; align-self: center; padding: 4px var(--aicl-space-3); }

[data-aicl='toast-dismiss'] {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: var(--aicl-radius-sm);
  background: transparent;
  color: var(--aicl-text-faint);
  font: inherit;
  cursor: pointer;
}

[data-aicl='toast-dismiss']:hover {
  background: var(--aicl-surface-tint);
  color: var(--aicl-text);
}

/* ═══ Form controls ═══════════════════════════════════════════════════ */

[data-aicl='field'] {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: var(--aicl-text-sm);
}

[data-aicl='field-label'] {
  font-weight: 500;
  color: var(--aicl-text);
}

[data-aicl='field-description'] {
  color: var(--aicl-text-faint);
  font-size: var(--aicl-text-xs);
}

[data-aicl='field-error'] {
  color: var(--aicl-danger);
  font-size: var(--aicl-text-xs);
}

[data-aicl='field'][data-invalid] input,
[data-aicl='field'][data-invalid] textarea,
[data-aicl='field'][data-invalid] [data-aicl='select-trigger'] {
  border-color: var(--aicl-danger);
}

[data-aicl='field-save-state'] {
  font-size: var(--aicl-text-xs);
  color: var(--aicl-text-faint);
}

[data-aicl='field'][data-save-state='saved'] [data-aicl='field-save-state'] { color: var(--aicl-success); }
[data-aicl='field'][data-save-state='error'] [data-aicl='field-save-state'] { color: var(--aicl-danger); }

[data-aicl='switch-root'] {
  display: inline-flex;
  align-items: center;
  gap: var(--aicl-space-2);
  font-size: var(--aicl-text-sm);
}

[data-aicl='switch'] {
  position: relative;
  flex: none;
  width: 36px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-border-strong);
  cursor: pointer;
  transition: background var(--aicl-anim-fast) var(--aicl-ease);
}

[data-aicl='switch'][data-state='checked'] {
  background: var(--aicl-accent);
}

[data-aicl='switch-thumb'] {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--aicl-surface);
  box-shadow: var(--aicl-shadow-1);
  transition: transform var(--aicl-anim-fast) var(--aicl-ease);
}

[data-aicl='switch'][data-state='checked'] [data-aicl='switch-thumb'] {
  transform: translateX(16px);
}

[data-aicl='switch'][data-save-state='saving'] { opacity: 0.7; cursor: progress; }
[data-aicl='switch'][data-save-state='error'] { box-shadow: 0 0 0 2px var(--aicl-danger); }
[data-aicl='switch']:disabled { opacity: 0.45; cursor: not-allowed; }

[data-aicl='select'] {
  position: relative;
  display: inline-block;
  min-width: 200px;
  font-size: var(--aicl-text-sm);
}

[data-aicl='select-trigger'] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--aicl-space-2);
  width: 100%;
  padding: 7px var(--aicl-space-3);
  border: 1px solid var(--aicl-border-strong);
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface);
  color: var(--aicl-text);
  font: inherit;
  text-align: start;
  cursor: pointer;
}

[data-aicl='select-trigger'] > [data-aicl='icon'] {
  color: var(--aicl-text-faint);
}

[data-aicl='select-value'] {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-aicl='select'][data-size='sm'] [data-aicl='select-trigger'] { padding: 4px var(--aicl-space-2); font-size: var(--aicl-text-xs); }
[data-aicl='select-trigger'][data-placeholder] { color: var(--aicl-text-faint); }

[data-aicl='select-trigger']:focus-visible {
  outline: none;
  border-color: var(--aicl-border-focus);
  box-shadow: var(--aicl-focus-ring);
}

[data-aicl='select-listbox'] {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 30;
  max-height: 280px;
  overflow-y: auto;
  margin: 0;
  padding: var(--aicl-space-1);
  list-style: none;
  background: var(--aicl-surface-elevated);
  border: 1px solid var(--aicl-border);
  border-radius: var(--aicl-radius-md);
  box-shadow: var(--aicl-shadow-2);
}

[data-aicl='select-listbox'] [role='option'] {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 6px 28px 6px var(--aicl-space-3);
  border-radius: var(--aicl-radius-sm);
  cursor: default;
}

[data-aicl='select-listbox'] [role='option'][data-active] { background: var(--aicl-surface-tint); }
[data-aicl='select-listbox'] [role='option'][aria-selected='true'] { color: var(--aicl-accent-strong); font-weight: 500; }
[data-aicl='select-listbox'] [role='option'][aria-disabled='true'] { color: var(--aicl-text-faint); }

[data-aicl='select-option-description'] {
  font-size: var(--aicl-text-xs);
  font-weight: 400;
  color: var(--aicl-text-faint);
}

[data-aicl='segmented'] {
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border-radius: var(--aicl-radius-md);
  background: var(--aicl-surface-inset);
  font-size: var(--aicl-text-sm);
}

[data-aicl='segmented-item'] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px var(--aicl-space-3);
  border: 0;
  border-radius: calc(var(--aicl-radius-md) - 2px);
  background: transparent;
  color: var(--aicl-text-muted);
  font: inherit;
  cursor: pointer;
}

[data-aicl='segmented-item'][aria-checked='true'] {
  background: var(--aicl-surface);
  color: var(--aicl-text);
  box-shadow: var(--aicl-shadow-1);
}

[data-aicl='segmented-item']:focus-visible,
[data-aicl='switch']:focus-visible,
[data-aicl='sidebar-nav-item']:focus-visible,
[data-aicl='toast']:focus-visible,
[data-aicl='alert-dialog-cancel']:focus-visible,
[data-aicl='alert-dialog-confirm']:focus-visible {
  outline: 2px solid var(--aicl-ring);
  outline-offset: 2px;
}

[data-aicl='segmented-item']:disabled { opacity: 0.45; cursor: not-allowed; }

@media (prefers-reduced-motion: reduce) {
  [data-aicl='scrim'],
  [data-aicl='dialog'],
  [data-aicl='alert-dialog'],
  [data-aicl='drawer'],
  [data-aicl='toast'],
  [data-aicl='session-skeleton'],
  [data-aicl='attachment-progress']::after {
    animation: none;
  }
}

[data-aicl='select-option-check'] {
  position: absolute;
  top: 8px;
  right: 8px;
  color: var(--aicl-text);
}

[data-aicl='toast-icon'] {
  grid-row: 1 / span 2;
  padding-top: 1px;
  color: var(--aicl-info);
}

[data-aicl='toast'][data-variant='success'] [data-aicl='toast-icon'] { color: var(--aicl-success); }
[data-aicl='toast'][data-variant='error'] [data-aicl='toast-icon'] { color: var(--aicl-danger); }

[data-aicl='session-search'] {
  position: relative;
}

[data-aicl='session-search-icon'] {
  position: absolute;
  top: 18px;
  left: 20px;
  color: var(--aicl-text-faint);
  pointer-events: none;
}

[data-aicl='session-search-input'] {
  padding-left: 34px;
}

[data-aicl='dialog-close'] {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
}

/* ═══ Markdown prose (opt-in @aicl/react/markdown) ════════════════════ */

[data-aicl='part'][data-part='text'][data-format='markdown'] {
  white-space: normal;
}

[data-format='markdown'] > :first-child { margin-top: 0; }
[data-format='markdown'] > :last-child { margin-bottom: 0; }

[data-format='markdown'] p,
[data-format='markdown'] ul,
[data-format='markdown'] ol,
[data-format='markdown'] blockquote,
[data-format='markdown'] table,
[data-format='markdown'] [data-aicl='code-block'] {
  margin: 0 0 0.75em;
}

[data-format='markdown'] h1,
[data-format='markdown'] h2,
[data-format='markdown'] h3,
[data-format='markdown'] h4 {
  margin: 1.2em 0 0.5em;
  font-weight: 600;
  line-height: var(--aicl-leading-tight);
}

[data-format='markdown'] h1 { font-size: 1.35em; }
[data-format='markdown'] h2 { font-size: 1.2em; }
[data-format='markdown'] h3 { font-size: 1.05em; }
[data-format='markdown'] h4 { font-size: 1em; }

[data-format='markdown'] ul,
[data-format='markdown'] ol {
  padding-left: 1.4em;
}

[data-format='markdown'] li + li { margin-top: 0.25em; }
[data-format='markdown'] li > p { margin: 0; }

[data-format='markdown'] a {
  color: var(--aicl-text-link);
  text-decoration: underline;
  text-underline-offset: 2px;
  text-decoration-thickness: 1px;
}

[data-format='markdown'] blockquote {
  padding-left: var(--aicl-space-3);
  border-left: 2px solid var(--aicl-border-strong);
  color: var(--aicl-text-muted);
}

[data-format='markdown'] hr {
  margin: 1.2em 0;
  border: 0;
  border-top: 1px solid var(--aicl-border);
}

[data-aicl='inline-code'] {
  padding: 0.1em 0.35em;
  border-radius: 4px;
  background: var(--aicl-surface-inset);
  font-family: var(--aicl-font-mono);
  font-size: 0.88em;
}

[data-format='markdown'] table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  font-size: var(--aicl-text-sm);
}

[data-format='markdown'] th,
[data-format='markdown'] td {
  padding: 6px var(--aicl-space-3);
  border-bottom: 1px solid var(--aicl-border);
  text-align: left;
}

[data-format='markdown'] th {
  color: var(--aicl-text-muted);
  font-weight: 500;
}

[data-format='markdown'] input[type='checkbox'] {
  margin-right: 6px;
}

/* ─── Overlay and content set (AICL-144) ─────────────────────────── */

[data-aicl='badge'] {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
  padding: 0 8px;
  border: var(--aicl-border-width) solid transparent;
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-accent);
  color: var(--aicl-accent-fg);
  font-size: var(--aicl-type-caption);
  line-height: 1;
  white-space: nowrap;
}

[data-aicl='badge'][data-variant='secondary'] {
  background: var(--aicl-surface-muted, var(--aicl-surface-elevated));
  color: var(--aicl-text);
}

[data-aicl='badge'][data-variant='outline'] {
  background: transparent;
  border-color: var(--aicl-border);
  color: var(--aicl-text);
}

[data-aicl='badge'][data-variant='success'] {
  background: color-mix(in oklab, var(--aicl-success, #16a34a) 16%, var(--aicl-surface));
  color: var(--aicl-success, #16a34a);
}

[data-aicl='badge'][data-variant='warning'] {
  background: color-mix(in oklab, var(--aicl-warning, #ca8a04) 16%, var(--aicl-surface));
  color: var(--aicl-warning, #ca8a04);
}

[data-aicl='badge'][data-variant='danger'] {
  background: color-mix(in oklab, var(--aicl-danger) 16%, var(--aicl-surface));
  color: var(--aicl-danger);
}

[data-aicl='separator'] {
  background: var(--aicl-border);
}

[data-aicl='separator'][data-orientation='horizontal'] {
  height: 1px;
  width: 100%;
}

[data-aicl='separator'][data-orientation='vertical'] {
  width: 1px;
  height: 1em;
  align-self: stretch;
}

[data-aicl='kbd'] {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 0.1em 0.35em;
  border: var(--aicl-border-width) solid var(--aicl-border);
  border-radius: var(--aicl-radius-sm);
  background: var(--aicl-surface-elevated);
  box-shadow: 0 1px 0 var(--aicl-border);
  font-family: inherit;
  font-size: var(--aicl-type-caption);
  line-height: 1.4;
}

[data-aicl='kbd-key'] + [data-aicl='kbd-key']::before {
  content: '';
  margin-right: 2px;
}

[data-aicl='progress'] {
  position: relative;
  display: block;
  height: 6px;
  overflow: hidden;
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-surface-muted, var(--aicl-border));
}

[data-aicl='progress-fill'] {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background: var(--aicl-accent);
  transition: transform var(--aicl-anim-moderate) var(--aicl-ease);
}

[data-aicl='progress'][data-state='indeterminate'] [data-aicl='progress-fill'] {
  width: 40%;
  animation: aicl-progress-pulse 1.1s var(--aicl-ease) infinite;
}

@keyframes aicl-progress-pulse {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(280%); }
}

@media (prefers-reduced-motion: reduce) {
  [data-aicl='progress-fill'] {
    transition: none;
  }
  [data-aicl='progress'][data-state='indeterminate'] [data-aicl='progress-fill'] {
    animation: none;
    width: 100%;
    opacity: 0.5;
  }
}

[data-aicl='tooltip'] {
  position: relative;
  display: inline-flex;
}

[data-aicl='tooltip-content'] {
  position: absolute;
  z-index: 20;
  width: max-content;
  max-width: 16rem;
  padding: 4px 8px;
  border-radius: var(--aicl-radius-sm);
  background: var(--aicl-text);
  color: var(--aicl-surface);
  font-size: var(--aicl-type-caption);
  line-height: 1.3;
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--aicl-anim-fast) var(--aicl-ease);
}

[data-aicl='tooltip-content'][data-state='open'] {
  opacity: 1;
}

[data-aicl='tooltip-content'][data-side='top'] {
  bottom: calc(100% + 6px);
  left: 50%;
  translate: -50% 0;
}

[data-aicl='tooltip-content'][data-side='bottom'] {
  top: calc(100% + 6px);
  left: 50%;
  translate: -50% 0;
}

[data-aicl='tooltip-content'][data-side='start'] {
  right: calc(100% + 6px);
  top: 50%;
  translate: 0 -50%;
}

[data-aicl='tooltip-content'][data-side='end'] {
  left: calc(100% + 6px);
  top: 50%;
  translate: 0 -50%;
}

[data-aicl='collapsible-trigger'] {
  display: inline-flex;
  align-items: center;
  gap: var(--aicl-control-gap);
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

[data-aicl='collapsible-icon'] {
  display: inline-flex;
  transition: transform var(--aicl-anim-fast) var(--aicl-ease);
}

[data-aicl='collapsible-icon'][data-state='open'] {
  transform: rotate(180deg);
}

[data-aicl='collapsible-content'] {
  overflow: hidden;
}

[data-aicl='collapsible-content'][data-state='closed'] {
  display: none;
}

[data-aicl='tabs-list'] {
  position: relative;
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border: var(--aicl-border-width) solid var(--aicl-border);
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-surface-muted, var(--aicl-surface-elevated));
}

[data-aicl='tabs-indicator'] {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 0;
  width: 1px;
  border-radius: var(--aicl-radius-pill);
  background: var(--aicl-surface);
  box-shadow: var(--aicl-shadow-1);
  transform-origin: left center;
  transition:
    transform var(--aicl-anim-moderate) var(--aicl-ease);
  pointer-events: none;
}

[data-aicl='tabs-tab'] {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  height: calc(var(--aicl-control-height) - 10px);
  padding: 0 var(--aicl-space-3);
  border: 0;
  border-radius: var(--aicl-radius-pill);
  background: transparent;
  color: var(--aicl-text-muted);
  font: inherit;
  font-size: var(--aicl-type-secondary);
  cursor: pointer;
}

[data-aicl='tabs-tab'][data-state='active'] {
  color: var(--aicl-text);
}

[data-aicl='tabs-panel'] {
  margin-top: var(--aicl-space-3);
}

@media (prefers-reduced-motion: reduce) {
  [data-aicl='tabs-indicator'],
  [data-aicl='tooltip-content'],
  [data-aicl='collapsible-icon'] {
    transition: none;
  }
}

/**
 * AICL styles entrypoint. Importing this file once applies the token
 * contract, the chat-shell reset, and the component surface to every
 * `[data-aicl]` selector in the document.
 *
 * Theming is by `data-theme="light"` or `data-theme="dark"` on any
 * container above the chat surface. Without an explicit theme, the
 * media query follows the user's system preference.
 *
 * A **skin** is a separate, opt-in layer: it replaces the contract's values
 * wholesale. Import the skin's stylesheet after this one and name it on the
 * element:
 *
 *   import '@aicl/styles';
 *   import '@aicl/styles/themes/looseleaf.css';
 *
 *   <div data-aicl-root data-aicl-theme="looseleaf" data-theme="dark">
 *
 * The motion system is a third layer, also opt-in. It replaces the
 * contract's easings with real springs and adds the travelling hover
 * highlight and weight-without-reflow:
 *
 *   import '@aicl/motion/motion.css';
 */
@import './contract.css';
@import './reset.css';
@import './components.css';

/**
 * Reset scoped to AICL surfaces. Applied to the library's container via
 * `data-aicl-root`. Minimal and reversible: it strips UA chrome inside the
 * chat shell so the headless primitives render predictably, and leaves
 * the rest of the document alone.
 */

:where([data-aicl-root]) *,
:where([data-aicl-root]) *::before,
:where([data-aicl-root]) *::after {
  box-sizing: border-box;
}

[data-aicl-root] {
  font-family: var(--aicl-font-sans);
  font-size: var(--aicl-text-base);
  line-height: var(--aicl-leading-normal);
  color: var(--aicl-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

:where([data-aicl-root]) ::selection {
  background: var(--aicl-selection-bg);
  color: var(--aicl-text);
}

:where([data-aicl-root]) :where(button),
:where([data-aicl-root]) :where(input),
:where([data-aicl-root]) :where(textarea),
:where([data-aicl-root]) :where(select) {
  font: inherit;
  color: inherit;
}

:where([data-aicl-root]) :where(button) {
  background: transparent;
  border: 0;
  padding: 0;
  cursor: pointer;
  border-radius: var(--aicl-radius-sm);
  transition: background var(--aicl-anim-fast) var(--aicl-ease),
              color var(--aicl-anim-fast) var(--aicl-ease),
              transform var(--aicl-anim-fast) var(--aicl-ease);
}

:where([data-aicl-root]) :where(button:focus-visible),
:where([data-aicl-root]) :where(textarea:focus-visible),
:where([data-aicl-root]) :where([contenteditable='true']:focus-visible) {
  outline: none;
  box-shadow: var(--aicl-focus-ring);
}

:where([data-aicl-root]) :where(button:active:not(:disabled)) {
  transform: translateY(0.5px);
}

:where([data-aicl-root]) :where(button:disabled) {
  cursor: not-allowed;
  opacity: 0.5;
}

:where([data-aicl-root]) :where(textarea) {
  background: transparent;
  border: 0;
  outline: none;
  resize: none;
}

:where([data-aicl-root]) :where(p) { margin: 0; }
:where([data-aicl-root]) :where(ul, ol) { margin: 0; padding-inline-start: 1.2em; }

/* Respect reduced motion. */
@media (prefers-reduced-motion: reduce) {
  [data-aicl-root] *,
  [data-aicl-root] *::before,
  [data-aicl-root] *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
